from lib import *
S = SS('l24')
steps = [
    step("新建的 ref 每个都是 .git/refs 下的一个文件:main、dev、feat/x(分支名里的斜杠变成子目录)、轻量标签 v1 和注解标签 v2,共 5 个文件;dev 文件里是 88a540f9c578… 这样的 hash。此时没有 .git/packed-refs(ls 报 No such file)。", t=tl(S(1)), mark=lidx(S(1), 'refs/heads/feat/x', 'packed-refs: No such file'), done=lidx(S(1), 'refs/heads/dev', 'refs/heads/main', 'refs/tags/v1', 'refs/tags/v2', '88a540f9c578'), kv=KV([['松散 ref', '一个 ref 一个文件,内容是 hash'], ['分支名里的 /', '子目录'], ['packed-refs', '还不存在']], ['松散 ref'])),
    step("git pack-refs --all --prune 之后,find .git/refs -type f 没有任何输出:所有松散文件都被删掉,内容进了 .git/packed-refs。这个文件第一行是 # pack-refs with: peeled fully-peeled sorted,后面每行是“hash 空格 ref 名”,按名字排序;注解标签 refs/tags/v2 的下一行以 ^ 开头:^88a540f…,是它剥开之后指向的提交(peeled),这样解出 v2^{} 时不必再读 tag 对象。git rev-parse 解出的结果不变:dev 是 88a540f…,v2 是 a5b9e18…,v2^{} 是 88a540f…。", t=tl(S(2)), mark=lidx(S(2), '# pack-refs with', 'refs/tags/v2', '^88a540f'), done=lidx(S(2), 'refs/heads/dev', 'refs/heads/main', 'refs/tags/v1', 'a5b9e18fe2ee'), kv=KV([['packed-refs', '一个文件,按名字排序,一行一个 ref'], ['^ 行', '注解标签剥开后的提交(peeled)'], ['松散文件', '--prune 之后全部删除']], ['^ 行'])),
    step("同一个 ref 两处都有时,松散文件优先:在 main 上提交 2 之后,.git/refs/heads/main 里是新值 fc77d20f2047…(提交 2),packed-refs 里的 main 仍是旧值 88a540f9c578…(提交 1),git rev-parse main 取到新值。手工 rm .git/refs/heads/main 之后,git rev-parse main 变回 88a540f9c578…——松散文件一删,下面的旧记录就露出来了。", t=tl(S(3)), mark=lidx(S(3), 'rm .git/refs/heads/main', '手工删掉松散文件之后'), done=lidx(S(3), 'git rev-parse main = fc77d20f2047', 'fc77d20f2047'), kv=KV([['优先级', '松散 ref > packed-refs'], ['更新 ref', '写松散文件,不改 packed-refs'], ['删掉松散文件', '旧的 packed 值重新生效']], ['优先级'])),
    step("删除分支:dev 只在 packed-refs 里,git branch -D dev 要重写 packed-refs,之后 grep -c refs/heads/dev 得到 0;分支列表里剩 feat/x 和 main。新建后再删的 tmp1 是松散 ref,删掉文件就行,ls .git/refs/heads 里只剩 main。删除 packed 的 ref 比删松散的 ref 多一次文件重写,而且要和并发更新互斥。", t=tl(S(4)), mark=lidx(S(4), 'Deleted branch dev', 'Deleted branch tmp1'), done=lidx(S(4), '  0', 'feat/x', 'main'), kv=KV([['删 packed 的 ref', '重写 packed-refs'], ['删松散的 ref', '删一个文件'], ['结果', '两种都不会留下旧值']], ['删 packed 的 ref'])),
    step("ref 很多时的耗时(5000 个 tag,5 次中位数):松散状态下 5000 个文件,git tag -l 90.9 ms,git for-each-ref refs/tags 184.5 ms,git rev-parse t04999(单个)11.0 ms。git pack-refs --all --prune 之后松散文件 0 个,packed-refs 5002 行(header、5000 个 tag 加 main)、290,103 字节:git tag -l 降到 14.6 ms(快 6.2 倍),git for-each-ref 降到 111.4 ms,单个 rev-parse 是 10.8 ms——只查一个 ref 几乎没有变化。", t=tl(S(5)), mark=lidx(S(5), 'git tag -l | wc -l', 'git for-each-ref', 'git rev-parse t04999'), done=lidx(S(5), '5000', '5002', '290103'), b=bars([['tag -l(松散)', 90.9, '90.9 ms'], ['tag -l(packed)', 14.6, '14.6 ms'], ['for-each-ref(松散)', 184.5, '184.5 ms'], ['for-each-ref(packed)', 111.4, '111.4 ms']], 184.5, mark=[1, 3], done=[0, 2]), kv=KV([['列举所有 ref', '读一个文件比打开 5000 个文件快'], ['查单个 ref', '几乎没有差别'], ['packed-refs', '5002 行 / 290 KB']], ['列举所有 ref'])),
    step("git gc 默认会 pack-refs:两个新分支 b1、b2 在 gc 之后,find .git/refs -type f 没有输出(全进了 packed-refs,4 行 = header、main、b1、b2)。之后新建的 b3 又是一个松散文件 .git/refs/heads/b3,要等下一次 pack-refs 才会被合并进去。", t=tl(S(6)), mark=lidx(S(6), '.git/refs/heads/b3'), done=lidx(S(6), 'git gc -q', '  4'), kv=KV([['gc', '会 pack-refs --all --prune'], ['新 ref', '又是松散文件'], ['常态', '大部分 ref 在 packed-refs,少数新的是松散的']], ['常态'])),
]
A = mkarti('l24', 24, 'Git,refs,packed-refs,pack-refs,松散引用,真实验证,动画演示',
    '在真实仓库里看 ref 的两种存放:松散文件与 .git/packed-refs;pack-refs --prune 把 5 个 ref 移进一个按名字排序的文件(注解标签多一行 ^peeled);同一个 ref 两处都有时松散文件优先,删掉它旧值会重新露出;删 packed 的分支要重写 packed-refs;5000 个 tag 时 git tag -l 从 90.9 ms 降到 14.6 ms,单个查找没有变化;git gc 默认会 pack-refs。',
    'git 的分支和标签存在哪里?为什么有的在 .git/refs 下是文件,有的又在 packed-refs 里?两个地方都有的时候谁说了算?这篇用真实命令看清文件结构、优先级、删除的行为,再测 5000 个标签时两种存放的耗时。',
    [('松散优先', '同一个 ref 两处都有时以 .git/refs 下的松散文件为准;删掉松散文件旧的 packed 值会重新生效'), ('90.9 → 14.6 ms', '5000 个 tag 时 git tag -l 在松散与 packed 下的耗时'), ('^ 行', 'packed-refs 里注解标签的下一行记着它剥开之后的提交')],
    [('松散 ref', '<p>每个分支或标签是 <code>.git/refs</code> 下的一个文件,内容就是 hash,分支名里的斜杠变成子目录。创建、更新 ref 都是写这个小文件,所以很便宜。</p>'),
     ('packed-refs', '<p><code>git pack-refs --all --prune</code> 把它们收进 <code>.git/packed-refs</code>:第一行说明特性(<code>peeled fully-peeled sorted</code>),之后每行“hash ref 名”,按名字排序。注解标签的下一行以 <code>^</code> 开头,记着剥开后的提交,查 <code>v2^{}</code> 不用再读 tag 对象。</p>'),
     ('谁优先', '<p>松散文件优先于 packed-refs。更新 ref 只写松散文件、不碰 packed-refs,所以 packed-refs 里的旧值会一直在那里,直到 pack-refs 再次运行。手工删掉松散文件会让旧值“复活”,这是手工操作 <code>.git</code> 的一个坑。</p>'),
     ('删除', '<p>删 packed 的 ref 要重写整个 packed-refs(并和别的更新互斥),删松散的 ref 只是删一个文件。两种都不会留下旧值。</p>'),
     ('性能', '<p>列举很多 ref 时,读一个文件比打开几千个文件快得多:5000 个 tag 的 <code>git tag -l</code> 快了约 6 倍;只查一个 ref 则几乎没有差别。</p>'),
     ('gc', '<p><code>git gc</code> 默认会执行 <code>pack-refs</code>,新创建的 ref 又是松散文件,下次 gc 再合并。所以常态是“大部分在 packed-refs,少数新的是松散的”。</p>')],
    steps,
    [ENV_I_GIT + '。5000 个 tag 用 git update-ref --stdin 批量创建;耗时是 5 次中位数,含进程启动;输出里 hash 缩写为前几位',
     '没有验证:reftable 后端(下一篇单独讲);ref 总数到十万级时 packed-refs 的行为;并发更新 packed-refs 时的锁(packed-refs.lock);git clone 下来的 ref 是否直接放进 packed-refs(没有查看);for-each-ref 在 packed 下仍要 111 ms 的原因(没有深挖)'],
    'packed-refs 与松散 ref')
